package com.nexushr.controller;
import com.nexushr.model.*;import com.nexushr.repo.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/leaves") public class LeaveController{final LeaveRequestRepository r;final EmployeeRepository er;public LeaveController(LeaveRequestRepository r,EmployeeRepository e){this.r=r;er=e;}
@org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @GetMapping public List<LeaveRequest> all(){return r.findAll();}
@org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @PostMapping public LeaveRequest create(@RequestBody LeaveRequest x){if(x.employee==null||x.employee.id==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"employee.id required");x.employee=er.findById(x.employee.id).orElseThrow();x.status=LeaveStatus.PENDING;x.createdAt=LocalDateTime.now();return r.save(x);}
@org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','HR')") @PutMapping("/{id}/status") public LeaveRequest status(@PathVariable Long id,@RequestParam LeaveStatus value){var x=r.findById(id).orElseThrow();if(x.status!=LeaveStatus.MANAGER_APPROVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Manager approval is required before HR final approval");if(value!=LeaveStatus.APPROVED&&value!=LeaveStatus.REJECTED)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"HR can only approve or reject");x.status=value;return r.save(x);}}
